{"plan": "O programa set_value apenas copia bytes para a conta PDA derivada de [b"data", user.key()]; nao ha aritmetica. O Static Agent concluiu corretamente que nao configura MATH. Vou montar o cenario legitimo: criar a conta PDA com o layout esperado (8 bytes de discriminador/prefixo, 32 bytes de user, 8 bytes de value, 1 byte de bump) e chamar set_value com um valor normal. O ataque tentaria um valor extremo (u64::MAX) para verificar se ha overflow, mas como nao ha operacao aritmetica, o valor e apenas gravado; o efeito medido seria o valor gravado igual ao enviado, o que nao constitui dano. Portanto a hipotese MATH e bloqueada por ausencia de aritmetica.", "scenario": "let user = Pubkey::new_unique();
let (pda, bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

let mut data_bytes = vec![0u8; 49];
data_bytes[8..40].copy_from_slice(user.as_ref());
data_bytes[40..48].copy_from_slice(&0u64.to_le_bytes());
data_bytes[48] = bump;

let data_account = account(&env.program_id, &data_bytes, None);
let user_account = wallet(1_000_000_000);

let contas = vec![
    (pda, data_account.clone()),
    (user, user_account.clone()),
];

let mut ix_data = vec![1u8];
ix_data.extend_from_slice(&42u64.to_le_bytes());
let ix = env.raw_ix(&ix_data, &[
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, true),
]);

let r = env.baseline("set_value legitimo", &ix, &contas);

let mut attack_data = vec![1u8];
attack_data.extend_from_slice(&u64::MAX.to_le_bytes());
let attack_ix = env.raw_ix(&attack_data, &[
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, true),
]);

let atk = env.attack("set_value com u64::MAX", &attack_ix, &contas);

if atk.program_result == ProgramResult::Success {
    let valor_gravado = read_u64(after(&atk, &pda).data(), 40);
    env.effect("valor gravado igual ao enviado (sem overflow)", valor_gravado == u64::MAX);
}"}

